def restore_archived_gallery_records(apps, schema_editor):
    GalleryImage = apps.get_model('gallery', 'GalleryImage')
    AuditLog = apps.get_model('audit', 'AuditLog')
    allowed_categories = {'STUDIO', 'CAFE', 'EVENTS', 'BEHIND_THE_SCENES'}
    for event in AuditLog.objects.filter(action='GALLERY_IMAGE_ARCHIVE').iterator():
        metadata = event.metadata if isinstance(event.metadata, dict) else {}
